# nhóm "Khác" cho mỗi nhóm: id = g+'_other'
if __name__ == "__main__":
    import json
    groups=[{"id":g,"ic":ic,"vi":vi,"en":en} for g,ic,vi,en in G]
    inds=[{"id":i,"g":g,"vi":vi,"en":en,"ic":ic,"kw":kw} for i,g,vi,en,ic,kw in I]
    for g,ic,vi,en in G:
        inds.append({"id":g+"_other","g":g,"vi":"Khác ("+vi.split(" &")[0].split(" ·")[0]+")","en":"Other","ic":"➕","kw":"(?!)"})
    js="const TAX="+json.dumps({"groups":groups,"inds":inds},ensure_ascii=False,separators=(',',':'))+";\n"
    open("taxonomy.js","w",encoding="utf-8").write(js)
    print(len(groups),"nhóm",len([x for x in inds if not x['id'].endswith('_other')]),"ngành",len(js),"bytes")
